class Solution {
public:
    int countLetters(string s) {
        int run = 0;
        int total = 0;
        for (int i = 0; i < static_cast<int>(s.size()); ++i) {
            if (i > 0 && s[i] == s[i - 1]) {
                ++run;
            } else {
                run = 1;
            }
            total += run;
        }
        return total;
    }
};
